VALUES ('f_6e1d93a0c4b72f85d39a0e', 'Bridge angels', 'application/vnd.google-apps.spreadsheet', '["d_63fffeb4fab5233ed5bb73"]', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "robert@harmonygames.co", "arthur.blake@harmonygames.co"]', '[{"email": "frederick.stone@harmonygames.co", "role": "reader"}, {"email": "robert@harmonygames.co", "role": "reader"}, {"email": "arthur.blake@harmonygames.co", "role": "reader"}]', 'private', '["leonard.hayes@harmonygames.co"]', '2025-09-20T03:15:00Z', '2025-09-19T17:52:00Z', false, false);
