tures", "[REDACTED]", "Seed", "", "Matteo Vallone", "London", "[URL_4975]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [16, "Initial Capital", "[URL_4976]", "Seed", "", "[PERSON_NAME_2309]", "Bay Area", "[URL_4977]", "", "", "", "", "[PERSON_NAME_2320] invested a small check.", "They won''t lead - would potentially write a small check", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [17, "Sweet Capital", "[REDACTED]", "Seed", "", "Christian Dörffer", "London", "[URL_4979]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [18, "Konvoy Ventures", "[REDACTED]", "Seed", "Yes", "Jackson Vaughan", "NYC", "[URL_3653]", "", "", "P2", "", "", "", "Dont invest in content", "", "", "", "", "", "", "", "", "", "", "", "", ""], [19, "Betaworks Ventures", "[REDACTED]", "Seed", "", "Peter Rojas", "Bay Area", "[URL_4982]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [20, "Courtside Ventures", "[REDACTED]", "Seed", "", "Deepen Parikh", "NYC", "[URL_4984]", "", "", "P2", "", "", "", "Not investing in gaming rn", "", "", "", "", "", "", "", "", "", "", "", "", ""], [21, "MaC Venture Capital", "[REDACTED]", "Seed", "", "Michael Palank", "LA", "[URL_4986]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [22, "Progression Fund", "[REDACTED]", "Seed", "", "Matt Lee", "Bay Area", "[URL_4988]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [23, "Progression Fund", "[REDACTED]", "Seed", "", "Mark Linao", "LA", "[URL_4989]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [24, "Signia Venture Partners", "[REDACTED]", "Seed", "", "Sunny Dhillon", "Bay Area", "[URL_4991]", "", "Kris", "", "", "They don''t invest in gaming anymore", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [25, "Backed.vc", "[REDACTED]", "Seed", "", "[PERSON_NAME_2310]", "London", "[URL_4993]", "", "Kris", "", "", "They don''t invest in gaming anymore", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [26, "The Venture Reality Fund", "[REDACTED]", "Seed", "", "Tipatat Chennavasin", "Bay Area", "[URL_4995]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [27, "Presence Capital", "[REDACTED]", "Seed", "", "Amitt Mahajan", "New Zealand", "[URL_4997]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [28, "Colopl Next", "[REDACTED]", "Seed", "", "Shintaro Yamakami", "Tokyo", "[URL_4999]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [29, "Everblue Management", "[REDACTED]", "Family Office", "Yes", "Dylan Glendinning", "NYC", "[URL_5000]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [30, "Dune Ventures", "[REDACTED]", "Family Office", "Yes", "David Brillembourg Jr", "NYC", "[URL_5002]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [31, "Galaxy Interactive", "[REDACTED]", "Seed/Series A", "Yes", "Richard Kim", "NYC", "[URL_5004]", "", "", "", "", "Our contact [PERSON_NAME_3050] left the company, need a new contact [PERSON_NAME_0451], need to ask [PERSON_NAME_1909] to see if we can get a new intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [32, "BITKRAFT Ventures", "[REDACTED]", "Seed/Series A", "Yes", "Scott Rupp", "Bay Area", "[URL_5006]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [33, "BITKRAFT Ventures", "[REDACTED]", "Seed/Series A", "Yes", "Malte Barth", "London", "[URL_5007]", "", "", "", "", "", "", "", "akin can intro", "", "", "", "", "", "", "", "", "", "", "", ""], [34, "Makers Fund", "[REDACTED]", "Seed/Series A", "Yes", "Michael Cheung", "London", "[URL_5009]", "", "", "", "", "They liked us but not enough to invest into us - we really liked [PERSON_NAME_0307] though, they are worthwhile pinging", "Reached out - no response as of 09/11", "", "akin can intro ", "", "", "", "", "", "", "", "", "", "", "", ""], [35, "Maveron", "[REDACTED]", "Seed/Series A", "", "David Wu", "Bay Area", "[URL_5011]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [36, "Canaan Ventures", "[REDACTED]", "Seed/Series A", "", "Laura Chau", "NYC", "[URL_5013]", "", "", "", "", "Need an intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [37, "March Gaming Fund", "[REDACTED]", "Seed/Series A", "", "[PERSON_NAME_8808]", "LA", "[URL_5015]", "", "Kris", "", "Rejected", "They liked us but it was a last minute meeting - the last note from them was Hi Leonard Hayes,\\n\\nThank you for letting me know about the term sheet.  \\n\\nI am interested in continuing the discussion, but unfortunately, I do not think we can meet a timeline that will be respectful of where you are in the fundraising process.  I have discussed the opportunity with my colleague [PERSON_NAME_2323] and our next step which we are currently working on is to internally review the market and opportunity for [PERSON_NAME_1350] and tile matching games.  I have tried [PERSON_NAME_2400] and was planning to look at some others in those categories.   Our diligence would normally include a review of the financial model with you and reference checking which would take at least until the end of the month as I am on vacation next week.  \\n\\nAs a former entrepreneur, my feelings is you should accept the term sheet, especially if you like the firm/partner and the terms are good.", "They don''t do bridge", "", "", "KS can intro", "", "", "", "", "", "", "", "", "", "", ""], [38, "Andreessen Horowitz", "[REDACTED]", "Seed/Series A", "", "[PERSON_NAME_2311]", "Bay Area", "[URL_5017]", "", "", "P0", "Initial Contact", "Good relationship with [PERSON_NAME_2325] and [PERSON_NAME_2324], they like us - applied to speedrun too ", "Waiting to hear back from them - they acknowledged our email, need to follow up", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [39, "Dentsu Ventures", "[REDACTED]", "Series A", "", "Kotaro Sasamoto", "Tokyo", "[URL_5019]", "", "", "", "", "", "", "IH to reach out", "", "", "", "", "", "", "", "", "", "", "", "", ""], [40, "LEGO Ventures", "[REDACTED]", "Series A", "Yes", "Parin Shah", "London", "[URL_5021]", "", "", "P0", "", "", "", "", "could be interesting ", "KS can intro", "", "", "", "", "", "", "", "", "", "", ""], [41, "Comcast Ventures", "[REDACTED]", "Series A", "", "", "", "", "", "", "", "", "Need Intro", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [42, "HP Tech Ventures", "[REDACTED]", "Series A", "", "Angelo Del Priore", "Bay Area", "[URL_5024]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [43, "Qualcomm Ventures", "[REDACTED]", "Series A", "", "Richard Tapalaga", "San Diego", "[URL_5026]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [44, "Bessemer Venture Partners", "[REDACTED]", "Series A", "", "Ethan Kurzweil", "Bay Area", "[URL_5028]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [45, "NFX", "[REDACTED]", "Series A", "", "Gigi Levy-Weiss", "Israel", "[URL_5030]", "", "", "", "", "", "", "", "akin can intro", "", "", "", "", "", "", "", "", "", "", "", ""], [46, "Upfront Ventures", "[REDACTED]", "Series A", "", "Kevin Zhang", "LA", "[URL_5032]", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""], [47, "Hiro Capital", "[REDACTED]", "Series A", "Yes", "[PERSON_NAME_2312]", "London", "[URL_5034]", "", "Kris", "", "Initial Contact", "We had a good convo with them but we already signed a deal with [PERSON_NAME_2000] at that point in time, will reach out", "Reached out - no response as of 09/11", "", "", "", "", "", "", "", "", "", "", "", "", "", "