VALUES ('1a68c2da0f36fc25489d3d9bbe9ccc32', '1757365500.384216', 'C096HFA5Z8W', 'message', 'EMPLOYEE_0038_SLACK_ID', '1AM Gaming is the March Gaming Fund row on our list, they renamed from March Capital. they passed on the re-seed, I forwarded you guys the email', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-08T21:05:00.000000Z', '{}');
