VALUES ('c183280a284440a6ca6cdbb5270c9139', '1758817200.730591', 'C096HFA5Z8W', 'message', 'EMPLOYEE_0038_SLACK_ID', 'correction on Play Ventures: the no I pasted here on the 15th was what they told Griffin, not us. that''s why I said they never answered us. it''s still their no for this round, the "discussing" Robert heard via Applovin doesn''t change that', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-25T16:20:00.000000Z', '{}');
