VALUES ('3cddf83c394676d8b72c0c20ed58f520', '1759274400.518306', 'C0880U9751A', 'message', 'EMPLOYEE_0025_SLACK_ID', 'Leonard - found a problem with investor android access: the investor tester list I made in the Play console never got attached to the internal testing track, so nobody on it has android yet (Karthic and the 3 Dentsu folks), even though ZOM-567 has them as added. testflight is fine for all of them. I''ll attach it when I push tomorrow''s build', NULL, '1759274400.518306', 1, 1, '1759276080.094417', false, NULL, '[]', '[]', '[]', '2025-09-30T23:20:00.000000Z', '{}');
