VALUES ('68c64270d660c977c4696986', 'commentCard', '2025-09-14T04:20:00Z', 'PERSON_6094_TRELLO_USER_ID', '640643a3fd8f3ca308d9318e', '68c5a49e8491a9d7faf869d0', '{"board": {"id": "640643a3fd8f3ca308d9318e", "name": "Harmony Games", "shortLink": "f4LGcmuh"}, "card": {"id": "68c5a49e8491a9d7faf869d0", "idShort": 455, "name": "Existing Investor Update", "shortLink": "MfMCBpMm"}, "idCard": "68c5a49e8491a9d7faf869d0", "list": {"id": "640643a3fd8f3ca308d93196", "name": "Doing"}, "text": "Going forward: anyone who passes on the bridge after we''ve actually pitched them on a call or meeting this round goes on a Keep warm checklist on this card, one item per firm, so they get the Q4 update with the rest. No''s from firms we only ever emailed don''t need it.", "textData": {"emoji": {}}}');
