VALUES ('arthur.blake@harmonygames.co/<CAxDeR9CSc9iEY-zACLQaU5Hff5KY0zkGE4PQ9iK@mail.gmail.com>', 'arthur.blake@harmonygames.co/1844724419788800015', 'arthur.blake@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Fred, I''m flying to LA tomorrow morning for the Griffin AGM and the Dentsu meeting, so can you take the send list for the Q4 investor update', 1759266300000, '2025-09-30T21:05:00Z', 1975, 'Q4 investor update - send list', 'leonard.hayes@harmonygames.co', 'Leonard Hayes', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '["Robert <robert@harmonygames.co>", "Arthur Blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Fred,\r\n\r\nI''m flying to LA tomorrow morning for the Griffin AGM and the Dentsu meeting, so can you take the send list for the Q4 investor update off my plate? It goes out the week after the Oct 14 board and I''ll write the update itself on the plane.\r\n\r\nOur existing investors are already on my own list. What I need from you is everyone from the bridge round who should get it, as of tonight, with the groups and details in the Q4 update send list doc so I know which paragraph each one gets. The draft update deck shows what each group gets. Get the new investors right, they''ll look for their own check in it.\r\n\r\nPlease put it in your Q4 investor update folder, the README in that folder says how to name it. Whatever the Existing Investor Update card says to do for firms that pass, do that too. Once it''s done reply here with how many firms and angels are in each group. I put Monday''s review on your calendar so we can go through it together.\r\n\r\nRobert asked about just sending it to everyone on the 2025 list. Let''s not, only the people the doc says.\r\n\r\nThanks,\r\nLeonard', NULL, '[{"name": "Message-ID", "value": "<CAxDeR9CSc9iEY-zACLQaU5Hff5KY0zkGE4PQ9iK@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 21:05:00 +0000"}, {"name": "Subject", "value": "Q4 investor update - send list"}, {"name": "From", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}, {"name": "Cc", "value": "Robert <robert@harmonygames.co>, Arthur Blake <arthur.blake@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('leonard.hayes@harmonygames.co/1844162278195200024', 'leonard.hayes@harmonygames.co', 'Leonard, Had another look at my numbers. I can do $25K this time, not the 40 we talked about. Send the docs over at 25 and I''ll sign. Anton', NULL);
